effect.shader:
const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);

vec4 calcGlint(vec2 vnorm, int nSamples, vec2 offsetScale) {

    vec4 output = vec4(0.0, 0.0, 0.0, 0.0);
    for(int i=1; i<nSamples; i++ ) {
        float p = float(i) / float(nSamples - 1);
        vec2 offs = vnorm * p;
        offs *= offsetScale;

        vec2 st1 = acScreenNorm.st-offs;
        vec4 texColor1 = (st1.x < 0. || st1.x > 1. || st1.y < 0. || st1.y > 1.) ? vec4(0.) : texture2DCv(inputImg.texture, st1);
        float luminance = dot(texColor1.rgb - thresholdColor.rgb, luminanceWeighting);
        output += luminance > threshold ? mix(texColor1,fillColor,blend)*(1.-p) : vec4(0.0);
    }
    return output;
}

#define PI 3.1415926536

void main() {
    if( acPass == 0 ) {
        gl_FragColor = texture2DCv(src.texture, acScreenNorm.st);
    }
    else {
        vec2 texelSize = 1.0 / getTexSize(inputImg.size);
        float speed = length(strength / 2.0 / texelSize);
        int nSamples = int(quality)/2;
        vec4 baseColor = texture2DCv(inputImg.texture,acScreenNorm.st);

        vec2 offsetScale = vec2(1., 1.);
        if( acScreenSize.y > acScreenSize.x ) {
            offsetScale.x *= acScreenSize.x / acScreenSize.y;
        } else {
            offsetScale.y *= acScreenSize.y / acScreenSize.x;
        }

        float angle = 360.0 / rayCount;
        vec4 outColor = vec4(0.);
        for(float i = 0.0; i < rayCount; i += 1.0) {
            float curRad = (angle*i + rayAngle) / 180.0 * PI;
            vec2 vnorm = vec2(cos(curRad),sin(curRad))*texelSize*speed;;
            outColor += calcGlint(vnorm, nSamples, offsetScale);
        }
        gl_FragColor = baseColor + outColor * intensity / float(nSamples);
    }
}
